# Code generated by wiregen. DO NOT EDIT.

import unittest

from Telemetry import Telemetry


def make_message():
    msg = Telemetry()
    msg.Set_device_id(3000000000)
    msg.Set_timestamp_us(12000000000)
    msg.Set_mode(5)
    msg.Set_status(5)
    msg.Set_armed(1)
    msg.Set_callsign(b"skywire")
    msg.Set_battery_mv(60000)
    return msg


class TelemetryTest(unittest.TestCase):
    def test_round_trip(self):
        msg = make_message()
        wire = msg.serialize()
        self.assertEqual(len(wire), msg.size())
        out = Telemetry()
        out.deserialize(wire)
        self.assertTrue(msg.equals(out), "round-trip value mismatch")
        self.assertEqual(msg, out)

    def test_short_buffer(self):
        wire = make_message().serialize()
        with self.assertRaises(ValueError):
            Telemetry().deserialize(wire[:-1])

    def test_set_mode_keeps_its_bits(self):
        msg = Telemetry()
        msg.Set_mode(0x15)
        self.assertEqual(msg.Get_mode(), 5)

    def test_set_status_keeps_its_bits(self):
        msg = Telemetry()
        msg.Set_status(0xd)
        self.assertEqual(msg.Get_status(), 5)

    def test_set_armed_keeps_its_bits(self):
        msg = Telemetry()
        msg.Set_armed(0x3)
        self.assertEqual(msg.Get_armed(), 1)

    def test_json(self):
        msg = make_message()
        text = msg.to_json()
        out = Telemetry()
        self.assertTrue(out.from_json(text))
        self.assertEqual(msg, out)
        self.assertEqual(out.to_json(), text)
        out = Telemetry()
        self.assertTrue(out.from_json(text.encode()))
        self.assertEqual(msg, out)

    def test_json_empty_is_default(self):
        out = make_message()
        self.assertTrue(out.from_json("{}"))
        self.assertEqual(out, Telemetry())

    def test_json_rejects(self):
        out = make_message()
        for text in (
            "",
            "[]",
            "{",
            "{\"x\":1}x",
            "{\"x\":1,}",
            "{\"device_id\":4294967296}",
            "{\"device_id\":true}",
            "{\"device_id\":1.5}",
            "{\"timestamp_us\":18446744073709551616}",
            "{\"timestamp_us\":true}",
            "{\"timestamp_us\":1.5}",
            "{\"mode\":16}",
            "{\"mode\":true}",
            "{\"mode\":1.5}",
            "{\"status\":8}",
            "{\"status\":true}",
            "{\"status\":1.5}",
            "{\"armed\":2}",
            "{\"armed\":true}",
            "{\"armed\":1.5}",
            "{\"callsign\":\"xxxxxxxxx\"}",
            "{\"position\":1}",
            "{\"battery_mv\":65536}",
            "{\"battery_mv\":true}",
            "{\"battery_mv\":1.5}",
        ):
            self.assertFalse(out.from_json(text), text)
        self.assertEqual(out, make_message())

    def test_xml(self):
        msg = make_message()
        text = msg.to_xml()
        out = Telemetry()
        self.assertTrue(out.from_xml(text))
        self.assertEqual(msg, out)
        self.assertEqual(out.to_xml(), text)
        out = Telemetry()
        self.assertTrue(out.from_xml(text.encode()))
        self.assertEqual(msg, out)

    def test_xml_empty_is_default(self):
        out = make_message()
        self.assertTrue(out.from_xml("<Telemetry/>"))
        self.assertEqual(out, Telemetry())

    def test_xml_rejects(self):
        out = make_message()
        for text in (
            "",
            "<Telemetry>",
            "<NotTelemetry/>",
            "<!DOCTYPE Telemetry><Telemetry/>",
            "<Telemetry>&unknown;</Telemetry>",
            "<Telemetry>text</Telemetry>",
            "<Telemetry><device_id>4294967296</device_id></Telemetry>",
            "<Telemetry><device_id><x/></device_id></Telemetry>",
            "<Telemetry><device_id>1.5</device_id></Telemetry>",
            "<Telemetry><timestamp_us>18446744073709551616</timestamp_us></Telemetry>",
            "<Telemetry><timestamp_us><x/></timestamp_us></Telemetry>",
            "<Telemetry><timestamp_us>1.5</timestamp_us></Telemetry>",
            "<Telemetry><mode>16</mode></Telemetry>",
            "<Telemetry><mode><x/></mode></Telemetry>",
            "<Telemetry><mode>1.5</mode></Telemetry>",
            "<Telemetry><status>8</status></Telemetry>",
            "<Telemetry><status><x/></status></Telemetry>",
            "<Telemetry><status>1.5</status></Telemetry>",
            "<Telemetry><armed>2</armed></Telemetry>",
            "<Telemetry><armed><x/></armed></Telemetry>",
            "<Telemetry><armed>1.5</armed></Telemetry>",
            "<Telemetry><callsign>xxxxxxxxx</callsign></Telemetry>",
            "<Telemetry><position>1</position></Telemetry>",
            "<Telemetry><battery_mv>65536</battery_mv></Telemetry>",
            "<Telemetry><battery_mv><x/></battery_mv></Telemetry>",
            "<Telemetry><battery_mv>1.5</battery_mv></Telemetry>",
        ):
            self.assertFalse(out.from_xml(text), text)
        self.assertEqual(out, make_message())

    def test_bson(self):
        msg = make_message()
        data = msg.to_bson()
        out = Telemetry()
        self.assertTrue(out.from_bson(data))
        self.assertEqual(msg, out)
        self.assertEqual(out.to_bson(), data)

    def test_bson_empty_is_default(self):
        out = make_message()
        self.assertTrue(out.from_bson(bytes.fromhex("0500000000")))
        self.assertEqual(out, Telemetry())

    def test_bson_large_uint64_timestamp_us(self):
        for value, element in ((2 ** 64 - 1, "1374696d657374616d705f757300ffffffffffffffff0000000000004030"), (2 ** 63 - 1, "1274696d657374616d705f757300ffffffffffffff7f")):
            msg = Telemetry()
            msg.Set_timestamp_us(value)
            data = msg.to_bson()
            self.assertIn(bytes.fromhex(element), data)
            out = Telemetry()
            self.assertTrue(out.from_bson(data))
            self.assertEqual(msg, out)

    def test_bson_rejects(self):
        good = make_message().to_bson()
        out = make_message()
        for data in (
            good[:-1],
            good + b"\x00",
            bytes([(good[0] + 1) % 256]) + good[1:],
            bytes.fromhex(""),
            bytes.fromhex("05000000"),
            bytes.fromhex("0600000000"),
            bytes.fromhex("0500000001"),
            bytes.fromhex("050000000000"),
            bytes.fromhex("0800000014780000"),
            bytes.fromhex("0c00000010ff000100000000"),
            bytes.fromhex(""),
            bytes.fromhex("18000000126465766963655f696400000000000100000000"),
            bytes.fromhex("18000000016465766963655f696400000000000000f83f00"),
            bytes.fromhex("11000000086465766963655f6964000100"),
            bytes.fromhex("230000001374696d657374616d705f7573000000000000000000010000000000403000"),
            bytes.fromhex("1b0000000174696d657374616d705f757300000000000000f83f00"),
            bytes.fromhex("1b0000001274696d657374616d705f757300ffffffffffffffff00"),
            bytes.fromhex("140000000874696d657374616d705f7573000100"),
            bytes.fromhex("0f000000106d6f6465001000000000"),
            bytes.fromhex("13000000016d6f646500000000000000f83f00"),
            bytes.fromhex("0c000000086d6f6465000100"),
            bytes.fromhex("1100000010737461747573000800000000"),
            bytes.fromhex("150000000173746174757300000000000000f83f00"),
            bytes.fromhex("0e00000008737461747573000100"),
            bytes.fromhex("100000001061726d6564000200000000"),
            bytes.fromhex("140000000161726d656400000000000000f83f00"),
            bytes.fromhex("0d0000000861726d6564000100"),
            bytes.fromhex("1d0000000263616c6c7369676e000a0000007878787878787878780000"),
            bytes.fromhex("1d0000000563616c6c7369676e00090000000078787878787878787800"),
            bytes.fromhex("150000000263616c6c7369676e0002000000ff0000"),
            bytes.fromhex("100000000863616c6c7369676e000100"),
            bytes.fromhex("1300000010706f736974696f6e000100000000"),
            bytes.fromhex("1000000008706f736974696f6e000100"),
            bytes.fromhex("1500000010626174746572795f6d76000000010000"),
            bytes.fromhex("1900000001626174746572795f6d7600000000000000f83f00"),
            bytes.fromhex("1200000008626174746572795f6d76000100"),
        ):
            self.assertFalse(out.from_bson(data), data.hex())
        self.assertEqual(out, make_message())


if __name__ == "__main__":
    unittest.main()
